CREATE TABLE public.transactions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, card_id UUID NOT NULL REFERENCES public.virtual_cards(id) ON DELETE CASCADE, merchant TEXT NOT NULL CHECK (char_length(merchant) >= 1 AND char_length(merchant) <= 120), amount_cents BIGINT NOT NULL CHECK (amount_cents > 0 AND amount_cents <= 100000000), occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), result TEXT NOT NULL CHECK (result IN ('approved','declined')), decline_code TEXT CHECK (decline_code IS NULL OR decline_code IN ('over_cap','frozen','closed','expired','insufficient_balance','other')), decline_reason TEXT CHECK (decline_reason IS NULL OR char_length(decline_reason) <= 500), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CHECK ((result = 'approved') OR (result = 'declined' AND decline_code IS NOT NULL))); ALTER TABLE public.transactions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.transactions ENABLE ROW LEVEL SECURITY;
CREATE INDEX transactions_card_id_idx ON public.transactions (card_id);
CREATE INDEX transactions_user_id_idx ON public.transactions (user_id);
CREATE INDEX transactions_occurred_at_idx ON public.transactions (occurred_at DESC);
CREATE INDEX transactions_result_idx ON public.transactions (result);
CREATE POLICY transactions_select_owner ON public.transactions FOR SELECT TO authenticated USING (auth.uid() = user_id);
CREATE FUNCTION public.record_transaction(p_card_id UUID, p_merchant TEXT, p_amount_cents BIGINT, p_result TEXT, p_decline_code TEXT DEFAULT NULL, p_decline_reason TEXT DEFAULT NULL) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$DECLARE v_user_id UUID := auth.uid(); v_id UUID; BEGIN IF v_user_id IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF; IF p_amount_cents IS NULL OR p_amount_cents <= 0 OR p_amount_cents > 100000000 THEN RAISE EXCEPTION 'amount over cap or invalid'; END IF; IF NOT EXISTS (SELECT 1 FROM public.virtual_cards AS v WHERE v.id = p_card_id AND v.user_id = v_user_id) THEN RAISE EXCEPTION 'card not owned'; END IF; INSERT INTO public.transactions (user_id, card_id, merchant, amount_cents, result, decline_code, decline_reason) VALUES (v_user_id, p_card_id, p_merchant, p_amount_cents, p_result, p_decline_code, p_decline_reason) RETURNING id INTO v_id; RETURN v_id; END;$$;
REVOKE ALL ON FUNCTION public.record_transaction(UUID, TEXT, BIGINT, TEXT, TEXT, TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.record_transaction(UUID, TEXT, BIGINT, TEXT, TEXT, TEXT) TO authenticated;
